import SwiftUI

/// One component Arcfin ships and its licence texts, from ThirdPartyLicenses.json. That file is
/// generated by .gitea/scripts/update-licenses.py from the resolved packages; edit the script,
/// not the file.
struct ThirdPartyLicense: Decodable, Identifiable, Hashable {
    struct LicenseText: Decodable, Hashable {
        let title: String
        let text: String
    }

    let id: String
    let name: String
    let version: String
    let license: String
    let url: String
    let note: String?
    let platforms: [String]?
    /// "arcfin" for Arcfin's own licence, policies and terms; nil for third-party components.
    let group: String?
    let texts: [LicenseText]

    var isArcfin: Bool { group == "arcfin" }

    /// Arcfin's licence and trademark policy have no version in the file; they're this app's.
    var shownVersion: String { version.isEmpty ? AppBuild.version : version }

    /// Arcfin's own documents in the app's language; everything else by its own name.
    var displayName: String {
        switch id {
        case "arcfin-trademark": String(localized: "Arcfin Name and Logo")
        case "arcfin-privacy": String(localized: "Privacy Policy")
        case "arcfin-terms": String(localized: "Terms of Use")
        case "arcfin-data-protection": String(localized: "Data Protection")
        case "apple-eula": String(localized: "Apple Standard EULA")
        default: name
        }
    }

    /// Every component that ships on this platform, in the file's order.
    static func bundled() -> [ThirdPartyLicense] {
        guard let url = Bundle.main.url(forResource: "ThirdPartyLicenses", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let all = try? JSONDecoder().decode([ThirdPartyLicense].self, from: data)
        else { return [] }
        return all.filter { $0.platforms?.contains(PlatformMetrics.licensePlatform) ?? true }
    }
}

struct LicensesView: View {
    @State private var licenses: [ThirdPartyLicense] = []

    var body: some View {
        List {
            Section("Data Sources") {
                Text("This product uses the TMDB API but is not endorsed or certified by TMDB.")
                    .tvReadOnlyRow()
                Text("Streaming availability is provided by JustWatch.")
                    .tvReadOnlyRow()
                Text("Awards come from Wikidata.")
                    .tvReadOnlyRow()
                Text("Lyrics not on your server come from LRCLIB.")
                    .tvReadOnlyRow()
                Text("Listening history, loves and Year in Music use ListenBrainz, a MetaBrainz Foundation project.")
                    .tvReadOnlyRow()
                // Only where the features are: on iPhone and iPad.
                if PlatformMetrics.identifiesSongs {
                    Text("Song recognition in What's Playing? is provided by Shazam.")
                        .tvReadOnlyRow()
                }
                if PlatformMetrics.playsAppleMusic {
                    Text("Songs not on your server can play from Apple Music, with a subscription.")
                        .tvReadOnlyRow()
                }
            }
            Section {
                ForEach(licenses.filter(\.isArcfin)) { entry in
                    row(entry)
                }
            } header: {
                Text(verbatim: "Arcfin")
            } footer: {
                Text("Arcfin's own licence, trademark policy and legal terms. The website has the current, binding version of each.")
                    .font(.caption)
                    .foregroundStyle(DT.Color.textSecondary)
            }
            Section {
                ForEach(licenses.filter { !$0.isArcfin }) { entry in
                    row(entry)
                }
            } footer: {
                Text("Open-source and third-party components Arcfin includes. Each shows its full licence, as written, and the exact version Arcfin is built with.")
                    .font(.caption)
                    .foregroundStyle(DT.Color.textSecondary)
            }
        }
        .arcfinListStyle()
        .screenBackground()
        .navigationTitle("Legal & Licenses")
        .inlineNavigationTitle()
        .task { if licenses.isEmpty { licenses = ThirdPartyLicense.bundled() } }
    }

    private func row(_ entry: ThirdPartyLicense) -> some View {
        NavigationLink {
            LicenseDetailView(entry: entry)
        } label: {
            LicenseRow(name: entry.displayName, license: entry.license, note: entry.shownVersion)
        }
    }
}

/// A component's version, source and licence texts. The texts are shown exactly as their
/// authors wrote them, in English, and never go through the String Catalog.
struct LicenseDetailView: View {
    let entry: ThirdPartyLicense

    var body: some View {
        List {
            Section {
                LabeledContent("Version") { Text(verbatim: entry.shownVersion) }
                    .tvReadOnlyRow()
                LabeledContent("License") { Text(verbatim: entry.license) }
                    .tvReadOnlyRow()
                if let url = URL(string: entry.url) {
                    if entry.isArcfin && entry.id != "arcfin" {
                        LicenseSourceRow(title: "Website", url: url)
                    } else {
                        LicenseSourceRow(title: "Source Code", url: url)
                    }
                }
            } footer: {
                if let note = entry.note {
                    Text(verbatim: note)
                        .font(.caption)
                        .foregroundStyle(DT.Color.textSecondary)
                }
            }
            ForEach(entry.texts, id: \.self) { text in
                Section {
                    ForEach(Array(Self.chunks(of: text.text).enumerated()), id: \.offset) { _, chunk in
                        Text(verbatim: chunk)
                            .font(.system(.caption, design: .monospaced))
                            .foregroundStyle(DT.Color.textPrimary)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .tvReadOnlyRow()
                    }
                } header: {
                    Text(verbatim: text.title)
                }
            }
        }
        .arcfinListStyle()
        .screenBackground()
        .navigationTitle(Text(verbatim: entry.displayName))
        .inlineNavigationTitle()
        .tvSettingsPage()
    }

    /// Paragraphs, with long ones cut at line breaks, so a long licence is many small rows
    /// instead of one huge text, and the remote can move through it on Apple TV.
    static func chunks(of text: String, maxLines: Int = 24) -> [String] {
        var out: [String] = []
        for paragraph in text.components(separatedBy: "\n\n") {
            let trimmed = paragraph.trimmingCharacters(in: .newlines)
            guard !trimmed.trimmingCharacters(in: .whitespaces).isEmpty else { continue }
            let lines = trimmed.components(separatedBy: "\n")
            stride(from: 0, to: lines.count, by: maxLines).forEach {
                out.append(lines[$0..<min($0 + maxLines, lines.count)].joined(separator: "\n"))
            }
        }
        return out
    }
}
